useEffect(()=>{
 if(!SUPABASE_URL||!SUPABASE_KEY){setSourceStatus("Modo demostración local · Supabase sin configurar");return;}
 let cancelled=false;
 const headers={apikey:SUPABASE_KEY,Authorization:"Bearer "+SUPABASE_KEY};
 Promise.all([
  fetch(SUPABASE_URL+"/rest/v1/products?select=id,slug,name,description,category,image_url,price_clp,compare_at_price_clp,active&active=eq.true&order=name.asc",{headers}),
  fetch(SUPABASE_URL+"/rest/v1/product_variants?select=id,product_id,color_name,color_hex,size_label,stock,sku",{headers})
 ]).then(async responses=>{
  if(responses.some(r=>!r.ok))throw new Error("No se pudo leer el catálogo");
  const [remoteProducts,variants]=await Promise.all(responses.map(r=>r.json()));
  const mapped=remoteProducts.map((p,index)=>{
   const vs=variants.filter(v=>v.product_id===p.id);
   const colorNames=[...new Set(vs.map(v=>v.color_name))];
   const sizeNames=[...new Set(vs.map(v=>v.size_label))];
   const stock={},variantIds={};
   vs.forEach(v=>{stock[v.color_name]??={};variantIds[v.color_name]??={};stock[v.color_name][v.size_label]=v.stock;variantIds[v.color_name][v.size_label]=v.id;});
   const colors=colorNames.map(name=>[name,vs.find(v=>v.color_name===name)?.color_hex||"#d8d8d0"]);
   const fallback=imageByCategory[p.category]||seed[index%seed.length].image;
   return {id:p.id,name:p.name,category:p.category,price:p.price_clp,old:p.compare_at_price_clp||null,tag:"Catálogo demo",colors,sizes:sizeNames,stock,variantIds,image:p.image_url||fallback,description:p.description||""};
  }).filter(p=>p.colors.length&&p.sizes.length);
  if(cancelled)return;
  if(mapped.length)setProducts(mapped);
  setSourceStatus("Conectado a Supabase · catálogo y stock por variante");
 }).catch(()=>{if(!cancelled)setSourceStatus("Supabase no disponible · se mantienen datos ficticios locales");});
 return()=>{cancelled=true;};
},[]);
